mapper.update:
update it_asset_request
applicant_id = #{applicantId}, status = #{status}, approver = #{approver}, handled_at = #{handledAt}, new_asset_no = #{newAssetNo}, remark = #{remark}, ding_instance_id = #{dingInstanceId}, ding_status = #{dingStatus}, ding_synced_at = #{dingSyncedAt}, ding_message = #{dingMessage}, handover_status = #{handoverStatus}, handover_by = #{handoverBy}, handover_at = #{handoverAt},
where id = #{id}

mapper.select:
select r.*, a.name as assetName, a.category as assetCategory
from it_asset_request r left join it_asset a on a.no = r.asset_no
where r.id = #{id}

select r.*, a.name as assetName, a.category as assetCategory
from it_asset_request r left join it_asset a on a.no = r.asset_no
where r.no = #{no}

select r.*, a.name as assetName, a.category as assetCategory,
  (select count(*) from it_missing_report m where m.status='PENDING' and m.requester_id =
    coalesce(r.applicant_id, (select case when count(*)=1 then min(u.id) end from sys_user u where u.name=r.applicant)))
  as pending_report_count
from it_asset_request r left join it_asset a on a.no = r.asset_no

  and r.status = #{status}
  and r.no = #{no}

    and (r.applicant_id = #{applicantId} or (r.applicant_id is null and r.applicant = #{applicant}
         and (select count(*) from sys_user u where u.name = r.applicant) = 1))

  and r.type = #{type}

order by case r.status when 'PENDING' then 0 else 1 end, r.created_at desc
limit 200
